{"code": "export async function main(input: unknown) {
  const culprits = ["mailer.ts in sendDigest", "billing.ts in chargeCard", "export.ts in writeCsv", "cleanup.ts in purgeOld"];
  const out: Record<string, unknown> = {};
  for (const c of culprits) {
    const r = await sdk.linear.searchIssues({ query: c });
    out[c] = r.issues;
  }
  // also broad searches
  out["__sendDigest"] = (await sdk.linear.searchIssues({ query: "sendDigest" })).issues;
  out["__chargeCard"] = (await sdk.linear.searchIssues({ query: "chargeCard" })).issues;
  out["__writeCsv"] = (await sdk.linear.searchIssues({ query: "writeCsv" })).issues;
  out["__purgeOld"] = (await sdk.linear.searchIssues({ query: "purgeOld" })).issues;
  return out;
}"}

{"code": "export async function main(input: unknown) {
  const out: Record<string, unknown> = {};
