{"code": "export async function main(input: unknown) {
  const targets = [
    { file: "src/jobs/mailer.ts", line: 31 },
    { file: "src/jobs/billing.ts", line: 77 },
    { file: "src/jobs/export.ts", line: 12 },
    { file: "src/jobs/cleanup.ts", line: 54 },
  ];
  const out = [];
  for (const t of targets) {
    try { out.push(await sdk.github.getBlame(t)); } catch (e) { out.push({ ...t, error: String(e) }); }
  }
  return out;
}"}

