{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 150);

  const checked = candidates.length;
  const missing: typeof candidates = [];
  for (const c of candidates) {
    const found = (await sdk.linear.searchIssues({ query: c.culprit })).issues;
    if (found.length === 0) missing.push(c);
  }

  const created: unknown[] = [];
  if (missing.length > 0) {
    const first = missing[0];
    const blame = await sdk.github.getBlame({ file: first.filename, line: first.lineNumber });
    const issue = await sdk.linear.createIssue({
      title: `[Sentry] ${first.title}`,
      description: first.culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push(issue);
  }

  return { checked, created };
}"}

